  px: 1 / 16, pt: 1 / 12, bp: 1 / 12, pc: 1, in: 6,
  cm: 6 / 2.54, mm: 6 / 25.4, dd: 1238 / 1157 / 12,
  cc: 1238 / 1157, nd: 685 / 642 / 12, nc: 685 / 642,
  sp: 1 / (65536 * 12), mu: 1 / 18,
